cat > /app/output/styles.css <<'CSS'
:root {
  --bg: #0d1117;
  --bg-elev: #111827;
  --bg-elev-2: #161b22;
  --text: #e6edf3;
  --muted: #9ba7b4;
  --border: #2a3441;
  --accent: #22d3ee;
  --accent-2: #22c55e;
  --danger: #ef4444;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  --radius: 14px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: radial-gradient(circle at 10% -10%, #0f172a 0%, var(--bg) 40%);
  color: var(--text);
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  line-height: 1.55;
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
.container { width: min(1200px, 92vw); margin: 0 auto; }
.topbar {
  position: sticky; top: 0; z-index: 20;
  background: rgba(13, 17, 23, 0.82);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}
.topbar-inner { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 0.85rem 0; }
.brand { display: flex; align-items: center; gap: .7rem; font-weight: 700; color: var(--text); }
.brand-dot { width: 10px; height: 10px; border-radius: 50%; background: linear-gradient(120deg, var(--accent), var(--accent-2)); box-shadow: 0 0 14px rgba(34,211,238,.7); }
.nav { display: flex; gap: .9rem; flex-wrap: wrap; }
.nav a { color: var(--muted); padding: .45rem .6rem; border-radius: 8px; }
.nav a.active, .nav a:hover { color: var(--text); background: #182235; text-decoration: none; }
.hero { padding: 4.5rem 0 2.5rem; }
.hero h1 { font-size: clamp(2rem, 4vw, 3.1rem); line-height: 1.1; margin: 0 0 .8rem; letter-spacing: -.02em; }
.hero p { color: var(--muted); max-width: 68ch; margin: 0 0 1.2rem; }
.btn-row { display: flex; flex-wrap: wrap; gap: .7rem; }
.btn { border: 1px solid var(--border); border-radius: 10px; padding: .65rem .95rem; color: var(--text); display: inline-flex; align-items: center; gap: .4rem; font-weight: 600; background: #111c2d; }
.btn.primary { background: linear-gradient(120deg, #0ea5e9, #22c55e); color: #021317; border: none; }
.btn:hover { text-decoration: none; filter: brightness(1.07); }
.section { padding: 1.1rem 0 2rem; }
.section h2 { margin: 0 0 .4rem; font-size: 1.5rem; }
.section .sub { color: var(--muted); margin: 0 0 1.1rem; }
.grid { display: grid; gap: 1rem; }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.card {
  border: 1px solid var(--border);
  background: linear-gradient(160deg, rgba(255,255,255,.03), rgba(255,255,255,.01));
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  padding: 1rem;
}
.card h3 { margin: 0 0 .45rem; }
.card p { margin: 0 0 .8rem; color: var(--muted); }
.pill { display: inline-block; font-size: .75rem; padding: .25rem .5rem; border: 1px solid var(--border); border-radius: 999px; color: #9ddbf6; }
.docs-layout { display: grid; grid-template-columns: 280px 1fr; min-height: calc(100vh - 58px); }
.sidebar {
  border-right: 1px solid var(--border);
  background: rgba(11, 18, 30, 0.78);
  position: sticky; top: 58px; height: calc(100vh - 58px);
  overflow-y: auto;
  transition: width .25s ease, transform .25s ease;
}
.sidebar-inner { padding: 1rem .75rem 2rem; }
.sidebar h4 { margin: .75rem .5rem .45rem; color: #9cc5da; font-size: .78rem; text-transform: uppercase; letter-spacing: .06em; }
.sidebar a { display: block; color: var(--muted); padding: .45rem .6rem; border-radius: 8px; font-size: .95rem; }
.sidebar a:hover, .sidebar a.active { background: #1a263a; color: var(--text); text-decoration: none; }
.sidebar.collapsed { width: 76px; }
.sidebar.collapsed .sidebar-text, .sidebar.collapsed h4 { display: none; }
.collapse-btn {
  width: 100%; text-align: left; border: 1px solid var(--border);
  background: #182235; color: var(--text); border-radius: 9px; padding: .5rem .65rem; cursor: pointer;
}
.main-doc { padding: 1.35rem 1.6rem 2.5rem; }
.kbd { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; background: #0b1220; border: 1px solid #2f3c4a; border-radius: 6px; padding: .05rem .35rem; }
.codebox { border: 1px solid var(--border); border-radius: 12px; overflow: hidden; background: #0b1220; }
.tablist { display: flex; border-bottom: 1px solid var(--border); }
.tab { border: 0; color: var(--muted); background: transparent; padding: .6rem .85rem; cursor: pointer; font-weight: 600; }
.tab.active { color: var(--text); border-bottom: 2px solid var(--accent); }
pre { margin: 0; padding: 1rem; overflow-x: auto; color: #d2e4f5; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: .9rem; }
.accordion { display: grid; gap: .6rem; }
.acc-item { border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
.acc-trigger { width: 100%; text-align: left; padding: .8rem .95rem; background: #121d2e; color: var(--text); border: 0; cursor: pointer; font-weight: 650; }
.acc-panel { display: none; padding: .85rem; border-top: 1px solid var(--border); background: #0f1828; }
.acc-item.open .acc-panel { display: block; }
.diagram { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: .75rem; }
.actor { text-align: center; padding: 1rem .6rem; border: 1px solid var(--border); border-radius: 12px; background: #101b2d; font-weight: 700; }
@media (max-width: 980px) {
  .grid-3 { grid-template-columns: 1fr 1fr; }
  .docs-layout { grid-template-columns: 1fr; }
  .sidebar { position: relative; top: 0; height: auto; border-right: 0; border-bottom: 1px solid var(--border); }
  .sidebar.collapsed { width: 100%; }
}
@media (max-width: 700px) {
  .grid-3, .grid-2, .diagram { grid-template-columns: 1fr; }
  .hero { padding-top: 3rem; }
}
